class Solution {
    public int splitArray(int[] nums, int k) {
        long lo = 0;
        long hi = 0;
        for (int n : nums) {
            lo = Math.max(lo, n);
            hi += n;
        }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (canSplit(nums, k, mid)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return (int) lo;
    }

    private boolean canSplit(int[] nums, int k, long maxSum) {
        int parts = 1;
        long cur = 0;
        for (int n : nums) {
            if (cur + n <= maxSum) {
                cur += n;
            } else {
                parts++;
                cur = n;
                if (parts > k) return false;
            }
        }
        return true;
    }
}

